  computed: {
    displayedPages() {
      const totalButtons = 10;
      const half = Math.floor(totalButtons / 2);
      let start = Math.max(1, this.page - half);
      let end = Math.min(this.tot_pages, start + totalButtons - 1);

      // Adjust start if we are near the end of the pagination
      if (end - start < totalButtons - 1) {
        start = Math.max(1, end - totalButtons + 1);
      }

      return Array.from({ length: end - start + 1 }, (_, i) => start + i);
