    validateSchedule() {
      console.log('dfff', this.selectedScheduleType, this.selectedScheduleType.code, typeof this.selectedScheduleType.code)
      if (this.selectedScheduleType.code === 'shift_based') {
        return this.shiftData.weekdays.some(day => day.selected && day.shifts.length > 0);
      }

      if (this.selectedScheduleType.code === 'monthly_days') {
        return this.shiftData.monthdays.some(day => day.selected && day.shifts.length > 0);
      }

      if (this.selectedScheduleType.code === 'work_rest_pattern') {
        return this.workGroups.some(group => group.shifts.length > 0);
      }

      return true;
    },

