        this.shiftData.weekdays[index].start_time = "07:00"; // Default start time (7 AM)
        this.shiftData.weekdays[index].end_time = "15:00"; // Default end time (3 PM)
      } else {
        this.shiftData.weekdays[index].start_time = ""; // Clear if unchecked
