    resetData() {
      // Reset Group Data
      this.workDaysPerGroup = null,
      this.restDays = null,
      this.workGroups = [
        {
          shifts: Array.from({ length: 1 }, () => [{ start_time: '', end_time: '', day: 1 }]),
          sameAsPrevious: false
        }
      ],

      // Reset weekdays
      this.shiftData.weekdays = Array.from({ length: 7 }, () => ({
        selected: false,
        hr_weekday_id: null,
        shifts: [
          {
            start_time: "",
            end_time: ""
          }
        ]
      }));

      // Reset monthdays (assuming current year and month)
      const year = new Date().getFullYear();
      const month = new Date().getMonth() + 1;
      const daysInMonth = new Date(year, month, 0).getDate();

      this.shiftData.monthdays = Array.from({ length: daysInMonth }, (_, i) => ({
        selected: false,
        hr_month_day_id: i + 1,
        shifts: [
          {
            start_time: "",
            end_time: ""
          }
        ]
      }));

      this.project_based = {
        has_salary: false
      }

      this.salaryItems = [
        {
          hr_salary_item_id: null,
          amount: 0,
        },
      ]
    },
    generateMonthDays() {
      const daysInMonth = 31;
      this.shiftData.monthdays = Array.from({ length: daysInMonth }, (_, i) => ({
        selected: false,
        hr_month_day_id: i + 1,
        shifts: [
          {
            start_time: "",
            end_time: ""
          }
        ]
      }));
    },
    addWorkGroup() {
      if (!this.canAddMoreGroups) return;

      const lastGroup = this.workGroups[this.workGroups.length - 1];
      const newGroup = {
        shifts: [],
        sameAsPrevious: false
      };

      const remainingDays = 31 - this.totalDays;
      const daysToAdd = Math.min(this.workDaysPerGroup, remainingDays);

      if (lastGroup.sameAsPrevious) {
        // Clone only up to remainingDays
        newGroup.shifts = lastGroup.shifts.slice(0, daysToAdd).map(dayShifts =>
          dayShifts.map(shift => ({ ...shift }))
        );
      } else {
        // Generate only the remaining number of days
        newGroup.shifts = Array.from({ length: daysToAdd }, (_, i) => [
          {
            start_time: '',
            end_time: '',
            day: i + 1
          }
        ]);
      }

      this.workGroups.push(newGroup);
    },
    totalDays() {
      return this.workGroups.reduce((sum, group) => {
        return sum + group.shifts.length + this.restDays;
      }, 0);
    },
    canAddMoreGroups() {
      return this.totalDays < 31;
    },
    addShift(groupIndex, dayIndex) {
      this.workGroups[groupIndex].shifts[dayIndex].push({
        start_time: '',
        end_time: '',
        day: dayIndex + 1
      });
    },
    removeShift(groupIndex, dayIndex, shiftIndex) {
      const shifts = this.workGroups[groupIndex].shifts[dayIndex];
      if (shifts.length > 1) {
        shifts.splice(shiftIndex, 1);
      }
    },
    deleteGroup(groupIndex) {
      if (this.workGroups.length > 1) {
        this.workGroups.splice(groupIndex, 1);
      }
    },
    updateStepperUI() {
      const progress = document.getElementById("progress");
      const circles = document.querySelectorAll(".circle");
      const content = document.querySelectorAll(".stepper-content");

      if (!this.currentValue || this.currentValue > circles.length) {
        this.currentValue = 1;
      }

      content.forEach((item, index) => {
        item.style.display = index === this.currentValue - 1 ? "block" : "none";
      });

      circles.forEach((circle, index) => {
        circle.classList.toggle("active", index < this.currentValue);
      });

      const actives = document.querySelectorAll(".circle.active");
      console.log('saa', actives)
      progress.style.width =
        ((actives.length - 1) / (circles.length - 1)) * 100 + "%";

      const next = document.getElementById("nextBtn");
      const prev = document.getElementById("prevBtn");
      const submit = document.getElementById("submit");

      submit.style.display = this.currentValue === circles.length ? "block" : "none";
      next.style.display = this.currentValue === circles.length ? "none" : "block";
      next.disabled = this.currentValue === circles.length;
      prev.disabled = this.currentValue <= 1;
    },
    handleSelectChange() {
    // Reset both
    this.form.loan.enabled = false;
    this.form.accrud.enabled = false;

    // Enable the selected one
    if (this.form.selectedOption === 'loan') {
      this.form.loan.enabled = true;
    } else if (this.form.selectedOption === 'accrud') {
      this.form.accrud.enabled = true;
    }
  },
  },
  watch: {
    'project_based.has_salary'() {
      this.$nextTick(() => {
        this.updateStepperUI(); // Recalculate circles and progress
      });
    },
    workDaysPerGroup(newVal) {
      const days = parseInt(newVal);
      this.workGroups.forEach(group => {
        if (group.shifts.length > days) {
          group.shifts.splice(days); // remove extra days
        } else {
          for (let i = group.shifts.length; i < days; i++) {
            group.shifts.push([
              {
                start_time: '',
                end_time: '',
                day: i + 1 // set correct day number
              }
            ]);
          }
        }

        // Also update existing day values
        group.shifts.forEach((dayShifts, i) => {
          dayShifts.forEach(shift => {
            shift.day = i + 1;
          });
        });
      });
    }
  },
  created() {
    let currentUser = JSON.parse(localStorage.currentUser);
    this.branch_id = currentUser.branch_id;
    this.get(1);
    // this.getEmps();
    this.getempsjob();
    this.getHrScheduleTypes();
    this.getconfig();
    this.getHrWeekDays();
    this.getEmpsCashAccounts();
    this.getAllSalaries();
    this.getConfigu()
  },
  mounted() {
    this.add_emp_modal =new Modal('#addemp');
    this.edit_emp_modal= new Modal('#editemps');
    this.generateMonthDays();
    document.getElementById("nextBtn").addEventListener("click", () => {
      this.currentValue = Math.min(this.currentValue + 1, document.querySelectorAll(".circle").length);
      this.updateStepperUI();
      this.generateMonthDays();
    });

    document.getElementById("prevBtn").addEventListener("click", () => {
      this.currentValue = Math.max(this.currentValue - 1, 1);
      this.updateStepperUI();
    });
    this.updateStepperUI();
  },
};
</script>

